import React,{useState} from 'react';
import {ResourceState} from '../../shared/ui.jsx';
import {useBoard} from './useBoard.js';
const statuses={planned:['计划','#8a94a6'],planted:['已埋设','#b882da'],developing:['推进中','#438fbf'],recovered:['已回收','#42a592'],abandoned:['已放弃','#d56c75']};
export function WritingOverview({call,novelId,tick,run,busy,onChapter,onForeshadow}){
 const resource=useBoard(call,novelId,tick),[target,setTarget]=useState(''),[volume,setVolume]=useState('all'),[status,setStatus]=useState(null),[start,setStart]=useState(0);
 const board=resource.value,s=board?.stats,rows=(s?.rows||[]).filter(r=>volume==='all'||(r.volumeId||'none')===volume),shown=rows.slice(start,start+50);
 return <div className="structure-page dashboard"><div className="row"><h2 className="grow">创作仪表盘</h2><small>已保存正文 · 含标点、不计空白</small></div><ResourceState resource={resource}>{s&&<><div className="stats-grid"><div><small>正文总字数</small><strong>{s.words.toLocaleString('zh-CN')}</strong></div><div><small>章节／事件</small><strong>{s.chapters} / {board.events.filter(e=>!e.deleted).length}</strong></div><div><small>角色／世界</small><strong>{board.nodes.filter(n=>n.type==='character_card').length} / {board.nodes.filter(n=>n.type!=='character_card').length}</strong></div></div><div className="dashboard-grid"><section className="chart-card chart-wide"><div className="row"><h3 className="grow">章节字数分布</h3><label>分卷<select aria-label="字数图分卷" value={volume} onChange={e=>{setVolume(e.target.value);setStart(0);}}><option value="all">全部分卷</option>{s.volumes.filter(v=>v.chapters).map(v=><option key={v.id||'none'} value={v.id||'none'}>{v.title}</option>)}</select></label></div><p className="muted">点击柱形打开该章。左右滑动查看；每段显示 50 章。</p><div className="chart-scroll" tabIndex={0} aria-label="分章字数柱状图，可横向滚动"><WordBars rows={shown} onChapter={onChapter}/></div>{rows.length>50&&<div className="row"><button disabled={!start} onClick={()=>setStart(Math.max(0,start-50))}>上一段</button><span>{start+1}–{Math.min(start+50,rows.length)}</span><button disabled={start+50>=rows.length} onClick={()=>setStart(start+50)}>下一段</button></div>}</section>
 <section className="chart-card chart-wide"><h3>累计正文曲线</h3><p className="muted">横轴为目录顺序，纵轴为累计字数；不表示每天写作量。</p><div className="chart-scroll" tabIndex={0} aria-label="累计字数曲线，可横向滚动"><Cumulative rows={s.rows} onChapter={onChapter}/></div></section>
 <section className="chart-card"><h3>写作目标</h3><GoalRing words={s.words} target={s.goal.target}/><div className="structure-form"><label>目标字数<input aria-label="目标字数" type="number" min="1" placeholder={s.goal.target?.toString()||'可不填'} value={target} onChange={e=>setTarget(e.target.value)}/></label><button disabled={busy||!!target&&(!Number.isSafeInteger(Number(target))||Number(target)<1)} onClick={()=>run(()=>call('writing.goal.set',{novelId,expectedRevision:s.goal.revision,target:target?Number(target):null,reason:'作者设置字数目标'}))}>{target?'保存目标':'清除目标'}</button></div></section>
 <section className="chart-card"><h3>伏笔进度</h3><ShadowDonut values={board.foreshadows} status={status} select={setStatus}/>{status&&<button className="quiet-button" onClick={()=>setStatus(null)}>查看全部伏笔</button>}{board.foreshadows.filter(f=>status?f.status===status:f.due||f.review).map(f=><div className="structure-entry" key={f.id}><button onClick={()=>onForeshadow(f.id)}>{f.title}</button>{f.due&&<small> · 已到计划回收章</small>}{f.review&&<small> · 正文依据需复核</small>}</div>)}</section></div></>}</ResourceState></div>;
}
function WordBars({rows,onChapter}){
 if(!rows.length)return <p className="chart-empty">保存正文后显示字数图。</p>;
 const width=Math.max(600,70+rows.length*36),max=Math.max(1,...rows.map(r=>r.words)),bar=(width-75)/rows.length;
 return <svg width={width} height="265" viewBox={`0 0 ${width} 265`} role="group" aria-label="章节字数柱状图">{[0,.25,.5,.75,1].map(f=><g key={f}><path d={`M55 ${220-f*180}H${width-10}`} stroke="var(--cg-line)"/><text x="5" y={224-f*180} fontSize="11" fill="var(--cg-muted)">{Math.round(max*f).toLocaleString()}</text></g>)}{rows.map((r,i)=>{const h=r.words/max*180,x=55+i*bar;return <g key={r.id} role="button" tabIndex={0} aria-label={`${r.title}：${r.words}字，打开章节`} className="svg-action" onClick={()=>onChapter(r.id)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' ')onChapter(r.id);}}><title>{r.title} · {r.words.toLocaleString()} 字</title><rect x={x+4} y={220-Math.max(3,h)} width={Math.max(4,bar-8)} height={Math.max(3,h)} rx="3" fill="var(--cg-accent)"/>{(rows.length<20||i%Math.ceil(rows.length/15)===0)&&<text x={x+bar/2} y="244" textAnchor="middle" fontSize="11" fill="var(--cg-muted)">{i+1}</text>}</g>;})}<text x={width/2} y="261" textAnchor="middle" fontSize="11" fill="var(--cg-muted)">章节顺序（当前范围）</text></svg>;
}
function Cumulative({rows,onChapter}){
 let total=0;const values=rows.map(r=>({...r,total:total+=r.words})),max=Math.max(1,total),x=i=>55+(values.length===1?0:i/(values.length-1))*610,y=v=>210-v/max*175,points=values.map((v,i)=>`${x(i)},${y(v.total)}`).join(' ');
 return <svg viewBox="0 0 690 250" className="responsive-chart" role="group" aria-label="累计正文字数曲线">{[0,.5,1].map(f=><g key={f}><path d={`M55 ${y(max*f)}H670`} stroke="var(--cg-line)"/><text x="4" y={y(max*f)+4} fill="var(--cg-muted)" fontSize="12">{Math.round(max*f).toLocaleString()}</text></g>)}{values.length>0&&<><polygon points={`55,210 ${points} ${x(values.length-1)},210`} fill="var(--cg-accent)" opacity=".12"/><polyline points={points} fill="none" stroke="var(--cg-accent)" strokeWidth="3"/>{values.map((v,i)=><g key={v.id} role="button" tabIndex={0} className="svg-action" aria-label={`${v.title} 累计 ${v.total} 字`} onClick={()=>onChapter(v.id)} onKeyDown={e=>{if(e.key==='Enter')onChapter(v.id);}}><title>{v.title} · 累计 {v.total.toLocaleString()} 字</title><circle cx={x(i)} cy={y(v.total)} r="6" fill="var(--cg-accent)"/></g>)}</>}<text x="360" y="243" fill="var(--cg-muted)" textAnchor="middle" fontSize="12">正文目录顺序</text></svg>;
}
function GoalRing({words,target}){const progress=target?Math.min(1,words/target):0;return <svg viewBox="0 0 240 160" className="goal-ring" role="img" aria-label={target?`目标完成 ${Math.round(words/target*100)}%`:'尚未设置目标'}><circle cx="120" cy="77" r="57" fill="none" stroke="var(--cg-line)" strokeWidth="12"/><circle cx="120" cy="77" r="57" fill="none" stroke="var(--cg-accent)" strokeWidth="12" pathLength="100" strokeDasharray={`${progress*100} 100`} transform="rotate(-90 120 77)"/><text x="120" y="76" fill="var(--cg-ink)" fontSize="26" textAnchor="middle">{target?`${Math.round(words/target*100)}%`:'—'}</text><text x="120" y="101" fill="var(--cg-muted)" fontSize="12" textAnchor="middle">{target?`${words.toLocaleString()} / ${target.toLocaleString()}`:'设置你的正文目标'}</text></svg>;}
function ShadowDonut({values,status,select}){const total=values.length;let offset=0;return <div className="donut-layout"><svg viewBox="0 0 180 180" role="group" aria-label="伏笔状态环形图"><circle cx="90" cy="90" r="60" fill="none" stroke="var(--cg-line)" strokeWidth="22"/>{Object.entries(statuses).map(([id,[name,color]])=>{const count=values.filter(f=>f.status===id).length,portion=total?count/total*100:0,at=offset;offset+=portion;return count?<circle key={id} cx="90" cy="90" r="60" fill="none" stroke={color} strokeWidth={status===id?28:22} pathLength="100" strokeDasharray={`${portion} ${100-portion}`} strokeDashoffset={-at} transform="rotate(-90 90 90)" role="button" tabIndex={0} aria-label={`${name} ${count}条伏笔`} onClick={()=>select(id)} onKeyDown={e=>{if(e.key==='Enter')select(id);}} className="svg-action"><title>{name} · {count} 条</title></circle>:null;})}<text x="90" y="89" fontSize="30" textAnchor="middle" fill="var(--cg-ink)">{total}</text><text x="90" y="111" fontSize="12" textAnchor="middle" fill="var(--cg-muted)">伏笔记录</text></svg><div>{Object.entries(statuses).map(([id,[name,color]])=><button key={id} className={`donut-key ${status===id?'selected':''}`} onClick={()=>select(status===id?null:id)}><span style={{background:color}}/>{name}<strong>{values.filter(f=>f.status===id).length}</strong></button>)}</div></div>;}
